            <div class="input-group">
                <label for="growthRate">월 성장률 (%)</label>
                <input type="number" id="growthRate" value="30" step="5" min="0" max="100">
            </div>
            <div class="input-group">
                <label for="fixedCost">월 고정비 (원)</label>
                <input type="number" id="fixedCost" value="80000000" step="1000000">
            </div>
            <div class="input-group">
                <label for="initialCash">초기 현금 (원)</label>
                <input type="number" id="initialCash" value="600000000" step="10000000">
            </div>
            <div class="input-group">
                <label for="cogsRate">COGS 비율 (%)</label>
                <input type="number" id="cogsRate" value="25" step="5" min="0" max="100">
