        <div class="chart-container">
            <div class="chart-title">누적 현금 흐름</div>
            <svg id="cashChart" width="100%" height="400"></svg>
            <div class="legend">
                <div class="legend-item">
                    <div class="legend-color" style="background-color: var(--series-3);"></div>
                    <span>누적 현금</span>
                </div>
            </div>
        </div>

        <div class="table-container">
            <div class="chart-title">상세 월별 데이터</div>
            <table id="dataTable">
                <thead>
                    <tr>
                        <th>월</th>
                        <th>MRR</th>
                        <th>ARR</th>
                        <th>월 매출</th>
                        <th>COGS</th>
                        <th>고정비</th>
                        <th>EBITDA</th>
                        <th>월 현금흐름</th>
                        <th>누적 현금</th>
                    </tr>
                </thead>
                <tbody id="tableBody"></tbody>
            </table>
