    <script>
        const inputs = {
            initialMrr: document.getElementById('initialMrr'),
            growthRate: document.getElementById('growthRate'),
            fixedCost: document.getElementById('fixedCost'),
            initialCash: document.getElementById('initialCash'),
            cogsRate: document.getElementById('cogsRate')
        };

        function formatCurrency(value) {
            return new Intl.NumberFormat('ko-KR', {
                style: 'currency',
                currency: 'KRW',
                minimumFractionDigits: 0,
                maximumFractionDigits: 0
            }).format(value);
        }

        function calculateFinancials() {
            const initialMrr = parseFloat(inputs.initialMrr.value);
            const growthRate = parseFloat(inputs.growthRate.value) / 100;
            const fixedCost = parseFloat(inputs.fixedCost.value);
            const initialCash = parseFloat(inputs.initialCash.value);
            const cogsRate = parseFloat(inputs.cogsRate.value) / 100;

            const data = [];
            let cumulativeCash = initialCash;

            for (let month = 1; month <= 12; month++) {
                const mrr = initialMrr * Math.pow(1 + growthRate, month - 1);
                const arr = mrr * 12;
                const monthlyRevenue = mrr;
                const monthlyCogs = arr * cogsRate / 12;
                const monthlyEbitda = arr - (arr * cogsRate) - (fixedCost * 12);
                const monthlyCashFlow = monthlyRevenue - monthlyCogs - fixedCost;
                cumulativeCash += monthlyCashFlow;

                data.push({
                    month,
                    mrr,
                    arr,
                    monthlyRevenue,
                    monthlyCogs,
                    fixedCost,
                    monthlyEbitda,
                    monthlyCashFlow,
                    cumulativeCash
                });
            }

            return data;
        }

        function renderKPIs() {
            const data = calculateFinancials();
            const lastMonth = data[11];
            const month12Cash = lastMonth.cumulativeCash;

            let runway = 12;
            for (let i = 0; i < data.length; i++) {
                if (data[i].cumulativeCash <= 0) {
                    runway = i + 1;
                    break;
                }
            }

            const kpiData = [
                { label: '12개월 MRR', value: lastMonth.mrr, delta: 'Month 1 대비 ' + Math.round((lastMonth.mrr / data[0].mrr - 1) * 100) + '%', status: 'up' },
                { label: '12개월 ARR', value: lastMonth.arr, delta: '연 매출액', status: '' },
                { label: '누적 현금', value: month12Cash, delta: '12개월 후', status: month12Cash > 0 ? 'up' : 'down' },
                { label: 'Runway', value: runway + '개월', delta: '현금 소진까지', status: runway >= 12 ? 'up' : 'down' }
            ];

            const kpiRow = document.getElementById('kpiRow');
            kpiRow.innerHTML = kpiData.map(kpi => `
                <div class="stat-tile ${kpi.status === 'up' ? 'good' : kpi.status === 'down' ? 'critical' : ''}">
                    <div class="stat-label">${kpi.label}</div>
                    <div class="stat-value">
                        ${typeof kpi.value === 'number' && kpi.label !== 'Runway' ? formatCurrency(kpi.value) : kpi.value}
                    </div>
                    <div class="stat-delta">${kpi.delta}</div>
                </div>
            `).join('');
        }

        function renderMRRChart() {
            const data = calculateFinancials();
            const svg = document.getElementById('mrrChart');
            const width = svg.clientWidth;
            const height = 400;
            const margin = { top: 20, right: 20, bottom: 40, left: 80 };
            const chartWidth = width - margin.left - margin.right;
            const chartHeight = height - margin.top - margin.bottom;

            const maxValue = Math.max(...data.map(d => d.arr));
            const scaleY = chartHeight / maxValue;
            const scaleX = chartWidth / 11;

            svg.innerHTML = '';

            // 그리드라인
            for (let i = 0; i <= 5; i++) {
                const y = margin.top + (chartHeight * i / 5);
                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                line.setAttribute('x1', margin.left);
                line.setAttribute('y1', y);
                line.setAttribute('x2', width - margin.right);
                line.setAttribute('y2', y);
                line.setAttribute('stroke', 'var(--gridline)');
                line.setAttribute('stroke-width', '1');
                svg.appendChild(line);
            }

            // 축
            const xAxis = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            xAxis.setAttribute('x1', margin.left);
            xAxis.setAttribute('y1', height - margin.bottom);
            xAxis.setAttribute('x2', width - margin.right);
            xAxis.setAttribute('y2', height - margin.bottom);
            xAxis.setAttribute('stroke', 'var(--baseline)');
            xAxis.setAttribute('stroke-width', '1');
            svg.appendChild(xAxis);

            // ARR 라인 (series-2)
            const arrPath = data.map((d, i) => {
                const x = margin.left + i * scaleX;
                const y = height - margin.bottom - d.arr * scaleY;
                return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
            }).join(' ');

            const arrLine = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            arrLine.setAttribute('d', arrPath);
            arrLine.setAttribute('stroke', 'var(--series-2)');
            arrLine.setAttribute('stroke-width', '2');
            arrLine.setAttribute('fill', 'none');
            arrLine.setAttribute('stroke-linecap', 'round');
            arrLine.setAttribute('stroke-linejoin', 'round');
            svg.appendChild(arrLine);

            // MRR 라인 (series-1)
            const mrrPath = data.map((d, i) => {
                const x = margin.left + i * scaleX;
                const y = height - margin.bottom - d.mrr * scaleY;
                return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
            }).join(' ');

            const mrrLine = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            mrrLine.setAttribute('d', mrrPath);
            mrrLine.setAttribute('stroke', 'var(--series-1)');
            mrrLine.setAttribute('stroke-width', '2');
            mrrLine.setAttribute('fill', 'none');
            mrrLine.setAttribute('stroke-linecap', 'round');
            mrrLine.setAttribute('stroke-linejoin', 'round');
            svg.appendChild(mrrLine);

            // 축 레이블
            data.forEach((d, i) => {
                const x = margin.left + i * scaleX;
                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', x);
                text.setAttribute('y', height - margin.bottom + 20);
                text.setAttribute('text-anchor', 'middle');
                text.setAttribute('font-size', '12');
                text.setAttribute('fill', 'var(--text-muted)');
                text.textContent = 'M' + d.month;
                svg.appendChild(text);
            });
        }

        function renderCashChart() {
            const data = calculateFinancials();
            const svg = document.getElementById('cashChart');
            const width = svg.clientWidth;
            const height = 400;
            const margin = { top: 20, right: 20, bottom: 40, left: 80 };
            const chartWidth = width - margin.left - margin.right;
            const chartHeight = height - margin.top - margin.bottom;

            const minValue = Math.min(...data.map(d => d.cumulativeCash));
            const maxValue = Math.max(...data.map(d => d.cumulativeCash));
            const range = maxValue - minValue;
            const scaleY = chartHeight / (range || 1);
            const scaleX = chartWidth / 11;

            svg.innerHTML = '';

            // 그리드라인
            for (let i = 0; i <= 5; i++) {
                const y = margin.top + (chartHeight * i / 5);
                const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
                line.setAttribute('x1', margin.left);
                line.setAttribute('y1', y);
                line.setAttribute('x2', width - margin.right);
                line.setAttribute('y2', y);
                line.setAttribute('stroke', 'var(--gridline)');
                line.setAttribute('stroke-width', '1');
                svg.appendChild(line);
            }

            // 영점 라인
            const zeroY = height - margin.bottom - (0 - minValue) * scaleY;
            const zeroLine = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            zeroLine.setAttribute('x1', margin.left);
            zeroLine.setAttribute('y1', zeroY);
            zeroLine.setAttribute('x2', width - margin.right);
            zeroLine.setAttribute('y2', zeroY);
            zeroLine.setAttribute('stroke', 'var(--baseline)');
            zeroLine.setAttribute('stroke-width', '2');
            zeroLine.setAttribute('stroke-dasharray', '4,4');
            svg.appendChild(zeroLine);

            // 축
            const xAxis = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            xAxis.setAttribute('x1', margin.left);
            xAxis.setAttribute('y1', height - margin.bottom);
            xAxis.setAttribute('x2', width - margin.right);
            xAxis.setAttribute('y2', height - margin.bottom);
            xAxis.setAttribute('stroke', 'var(--baseline)');
            xAxis.setAttribute('stroke-width', '1');
            svg.appendChild(xAxis);

            // 영역
            const areaPath = 'M ' + margin.left + ' ' + (height - margin.bottom) + ' ' +
                data.map((d, i) => {
                    const x = margin.left + i * scaleX;
                    const y = height - margin.bottom - (d.cumulativeCash - minValue) * scaleY;
                    return `L ${x} ${y}`;
                }).join(' ') +
                ` L ${width - margin.right} ${height - margin.bottom} Z`;

            const area = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            area.setAttribute('d', areaPath);
            area.setAttribute('fill', 'var(--series-3)');
            area.setAttribute('opacity', '0.1');
            svg.appendChild(area);

            // 라인
            const linePath = data.map((d, i) => {
                const x = margin.left + i * scaleX;
                const y = height - margin.bottom - (d.cumulativeCash - minValue) * scaleY;
                return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
            }).join(' ');

            const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
            line.setAttribute('d', linePath);
            line.setAttribute('stroke', 'var(--series-3)');
            line.setAttribute('stroke-width', '2');
            line.setAttribute('fill', 'none');
            line.setAttribute('stroke-linecap', 'round');
            line.setAttribute('stroke-linejoin', 'round');
            svg.appendChild(line);

            // 축 레이블
            data.forEach((d, i) => {
                const x = margin.left + i * scaleX;
                const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                text.setAttribute('x', x);
                text.setAttribute('y', height - margin.bottom + 20);
                text.setAttribute('text-anchor', 'middle');
                text.setAttribute('font-size', '12');
                text.setAttribute('fill', 'var(--text-muted)');
                text.textContent = 'M' + d.month;
                svg.appendChild(text);
            });
        }

        function renderTable() {
            const data = calculateFinancials();
            const tbody = document.getElementById('tableBody');

            tbody.innerHTML = data.map(d => `
                <tr>
                    <td><strong>Month ${d.month}</strong></td>
                    <td>${formatCurrency(d.mrr)}</td>
                    <td>${formatCurrency(d.arr)}</td>
                    <td>${formatCurrency(d.monthlyRevenue)}</td>
                    <td>${formatCurrency(d.monthlyCogs)}</td>
                    <td>${formatCurrency(d.fixedCost)}</td>
                    <td class="${d.monthlyEbitda > 0 ? 'positive' : 'negative'}">${formatCurrency(d.monthlyEbitda)}</td>
                    <td class="${d.monthlyCashFlow > 0 ? 'positive' : 'negative'}">${formatCurrency(d.monthlyCashFlow)}</td>
                    <td class="${d.cumulativeCash > 0 ? 'positive' : 'negative'}">${formatCurrency(d.cumulativeCash)}</td>
                </tr>
            `).join('');
        }

        function update() {
            renderKPIs();
            renderMRRChart();
            renderCashChart();
            renderTable();
        }

        Object.values(inputs).forEach(input => {
            input.addEventListener('change', update);
            input.addEventListener('input', update);
        });

        // 초기 렌더링
        update();

        // 윈도우 리사이즈 시 차트 다시 그리기
        window.addEventListener('resize', () => {
            renderMRRChart();
            renderCashChart();
        });
    </script>
</body>
</html>
