        }

        @media (prefers-color-scheme: dark) {
            :root:where(:not([data-theme="light"])) .viz-root {
                color-scheme: dark;
                --surface-1: #1a1a19;
                --surface-2: #0d0d0d;
                --text-primary: #ffffff;
                --text-secondary: #c3c2b7;
