                <button class="tab-btn bear active" data-scenario="bear">Bear (6%)</button>
                <button class="tab-btn base" data-scenario="base">Base (12%)</button>
                <button class="tab-btn bull" data-scenario="bull">Bull (20%)</button>
            </div>
            <table id="dataTable">
                <thead>
                    <tr>
                        <th>월</th>
                        <th>MRR</th>
                        <th>월 매출</th>
                        <th>원가</th>
                        <th>Contribution</th>
                        <th>고정비</th>
                        <th>월 현금흐름</th>
                        <th>누적 현금</th>
                    </tr>
                </thead>
