                if (item.post > 5) {
                    const labelAngle = currentAngle + sliceAngle / 2;
                    const labelRad = (labelAngle * Math.PI) / 180;
                    const labelRadius = radius * 0.65;
                    const labelX = cx + labelRadius * Math.cos(labelRad);
                    const labelY = cy + labelRadius * Math.sin(labelRad);

                    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                    text.setAttribute('x', labelX);
                    text.setAttribute('y', labelY);
                    text.setAttribute('text-anchor', 'middle');
                    text.setAttribute('dominant-baseline', 'central');
                    text.setAttribute('font-size', '12');
                    text.setAttribute('font-weight', '600');
                    text.setAttribute('fill', '#ffffff');
                    text.textContent = item.post.toFixed(1) + '%';
                    svg.appendChild(text);
                }

                currentAngle = endAngle;
            });
        }

        function renderLegend() {
            const legend = document.getElementById('legend');
            legend.innerHTML = capTable.map(item => `
                <div class="legend-item">
                    <div class="legend-color" style="background-color: ${item.color};"></div>
                    <div class="legend-label">${item.name}</div>
                    <div class="legend-value">${item.post.toFixed(2)}%</div>
                </div>
            `).join('');
        }

        // 초기 렌더링
        drawPieChart();
        renderLegend();
    </script>
</body>
</html>
```

