  <script>
    // ===== 데이터 및 계산 =====
    const COMMITMENT = 100; // 단위: 10억 원
    const MGMT_FEE_RATE = 0.02;
    const CARRY_RATE = 0.20;
    const HURDLE_RATE = 0.08;

    // 현금흐름 (Year 0-6, 음수는 call, 양수는 distribution)
    const GROSS_CASH_FLOWS = [0, -30, -25, -15, 20, 45, 80];
    const YEARS = [0, 1, 2, 3, 4, 5, 6];

    // 연도별 관리보수
    const MGMT_FEES = [0, 2, 2, 2, 2, 2, 2]; // 각 연도 약정액의 2%

    // Net 현금흐름
    const NET_CASH_FLOWS = GROSS_CASH_FLOWS.map((cf, i) => cf - MGMT_FEES[i]);

    // IRR 계산 함수
    function calculateIRR(cashFlows, times, initialGuess = 0.1) {
      const maxIterations = 100;
      const tolerance = 1e-6;
      let r = initialGuess;

      for (let i = 0; i < maxIterations; i++) {
        let npv = 0;
        let npvDerivative = 0;

        for (let j = 0; j < cashFlows.length; j++) {
          const cf = cashFlows[j];
          const t = times[j];
          const factor = Math.pow(1 + r, t);

          npv += cf / factor;
          if (t > 0) {
            npvDerivative -= (t * cf) / (Math.pow(1 + r, t + 1));
          }
        }

        if (Math.abs(npv) < tolerance) return r;
        if (Math.abs(npvDerivative) < 1e-10) break;

        r = r - npv / npvDerivative;
      }

      return r;
    }

    // MOIC 계산
    function calculateMOIC(cashFlows) {
      let inflows = 0;
      let outflows = 0;

      for (let cf of cashFlows) {
        if (cf > 0) inflows += cf;
        else outflows -= cf;
      }

      return outflows > 0 ? inflows / outflows : 0;
    }

    // 계산 실행
    const grossIRR = calculateIRR(GROSS_CASH_FLOWS, YEARS);
    const grossMOIC = calculateMOIC(GROSS_CASH_FLOWS);
    const netIRR = calculateIRR(NET_CASH_FLOWS, YEARS);
    const netMOIC = calculateMOIC(NET_CASH_FLOWS);

    // 총액 계산
    const totalInvested = 30 + 25 + 15; // 70
    const totalDistributed = 20 + 45 + 80; // 145
    const grossProfit = totalDistributed - totalInvested; // 75
    const totalMgmtFee = MGMT_FEES.reduce((a, b) => a + b, 0); // 12
    const netProfit = grossProfit - totalMgmtFee; // 63, 아니 배분액 기준으로 재계산

    // Hurdle 계산
    const hurdle = (
      30 * Math.pow(1.08, 5) +
      25 * Math.pow(1.08, 4) +
      15 * Math.pow(1.08, 3)
    );

    // Waterfall 계산
    const excessReturn = totalDistributed - hurdle;
    const lpHurdle = hurdle - totalInvested;
    const gpCarry = excessReturn * CARRY_RATE;
    const lpCarry = excessReturn * (1 - CARRY_RATE);
    const lpTotal = totalInvested + lpHurdle + lpCarry;
    const gpTotal = gpCarry + totalMgmtFee;

    // KPI 업데이트
    document.getElementById('gross-irr').textContent = (grossIRR * 100).toFixed(1) + '%';
    document.getElementById('gross-moic').textContent = grossMOIC.toFixed(2) + 'x';
    document.getElementById('net-irr').textContent = (netIRR * 100).toFixed(1) + '%';
    document.getElementById('net-moic').textContent = netMOIC.toFixed(2) + 'x';

    // 상세 분석 업데이트
    document.getElementById('total-invested').textContent = totalInvested;
    document.getElementById('total-distributed').textContent = totalDistributed;
    document.getElementById('gross-profit').textContent = grossProfit;
    document.getElementById('total-mgmt-fee').textContent = totalMgmtFee;
    document.getElementById('net-profit').textContent = (totalDistributed - totalMgmtFee);

    // Waterfall 상세 업데이트
    document.getElementById('lp-hurdle').textContent = lpHurdle.toFixed(0);
    document.getElementById('lp-hurdle-val').textContent = lpHurdle.toFixed(0);
    document.getElementById('excess-return').textContent = excessReturn.toFixed(0);
    document.getElementById('gp-carry').textContent = gpCarry.toFixed(0);
    document.getElementById('gp-carry-val').textContent = gpCarry.toFixed(0);
    document.getElementById('lp-carry').textContent = lpCarry.toFixed(0);
    document.getElementById('lp-carry-val').textContent = lpCarry.toFixed(0);
    document.getElementById('gp-total').textContent = gpTotal.toFixed(0);
    document.getElementById('lp-total').textContent = lpTotal.toFixed(0);

    // ===== Chart.js 설정 =====
    const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const colors = {
      blue: isDark ? '#3987e5' : '#2a78d6',
      orange: isDark ? '#d95926' : '#eb6834',
      aqua: isDark ? '#199e70' : '#1baf7a',
      red: isDark ? '#e66767' : '#e34948',
      text: isDark ? '#ffffff' : '#0b0b0b',
      textSecondary: isDark ? '#c3c2b7' : '#52514e',
      gridline: isDark ? '#2c2c2a' : '#e1e0d9',
    };

    Chart.defaults.color = colors.textSecondary;
    Chart.defaults.borderColor = colors.gridline;

    // 현금흐름 차트
    const cashFlowCtx = document.getElementById('cashFlowChart').getContext('2d');
    new Chart(cashFlowCtx, {
      type: 'bar',
      data: {
        labels: ['Year 0', 'Year 1', 'Year 2', 'Year 3', 'Year 4', 'Year 5', 'Year 6'],
        datasets: [
          {
            label: '자본 투자 (Call)',
            data: [0, 30, 25, 15, 0, 0, 0],
            backgroundColor: colors.red,
            borderRadius: 4,
            borderSkipped: false,
          },
          {
            label: '이익 배분 (Distribution)',
            data: [0, 0, 0, 0, 20, 45, 80],
            backgroundColor: colors.aqua,
            borderRadius: 4,
            borderSkipped: false,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            display: false,
          },
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: (value) => value + '억',
            },
            title: {
              display: true,
              text: '금액 (억 원)',
              color: colors.text,
              font: { size: 12, weight: 'bold' },
            },
          },
          x: {
            title: {
              display: true,
              text: '연도',
              color: colors.text,
              font: { size: 12, weight: 'bold' },
            },
          },
        },
      },
    });

    // Waterfall 차트
    const waterfallCtx = document.getElementById('waterfallChart').getContext('2d');
    const waterfallLabels = ['배분액', 'LP 자본', 'LP Hurdle', 'GP Carry', 'LP Carry'];
    const waterfallValues = [totalDistributed, totalInvested, lpHurdle, gpCarry, lpCarry];
    const waterfallColors = [colors.textSecondary, colors.orange, colors.orange, colors.blue, colors.orange];

    new Chart(waterfallCtx, {
      type: 'bar',
      data: {
        labels: waterfallLabels,
        datasets: [
          {
            label: '금액',
            data: waterfallValues,
            backgroundColor: waterfallColors,
            borderRadius: 4,
            borderSkipped: false,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        indexAxis: 'y',
        plugins: {
          legend: {
            display: false,
          },
        },
        scales: {
          x: {
            beginAtZero: true,
            ticks: {
              callback: (value) => value + '억',
            },
            title: {
              display: true,
              text: '금액 (억 원)',
              color: colors.text,
              font: { size: 12, weight: 'bold' },
            },
          },
        },
      },
    });
  </script>
